const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];

const state = {
  view: 'garage', points: [], drawing: false, drawingPoints: [], width: 12,
  weather: 'dry', grid: true, pits: false, location: 'monaco',
  session: 'race', laps: 3, credits: 12450, xp: 640, podiums: 0, races: 0,
  built: false, race: null, keys: new Set(), touch: new Set(), frame: 0,
};
const locations = {
  monaco: { name: 'MONACO', color: '#e9483f' }, italy: { name: 'ITALY', color: '#75bd73' },
  japan: { name: 'JAPAN', color: '#e989aa' }, singapore: { name: 'SINGAPORE', color: '#e9bd57' },
  belgium: { name: 'BELGIUM', color: '#76a780' }, australia: { name: 'AUSTRALIA', color: '#67b9ce' }, vegas: { name: 'LAS VEGAS', color: '#a788ee' },
};
const demoPoints = [
  [.17,.23],[.28,.15],[.40,.17],[.48,.27],[.61,.25],[.72,.16],[.83,.24],[.87,.39],
  [.79,.48],[.84,.59],[.78,.74],[.65,.80],[.55,.72],[.46,.82],[.32,.78],[.22,.68],
  [.27,.56],[.17,.49],[.12,.37],
];
const canvas = $('#track-canvas');
const ctx = canvas.getContext('2d');
const emptyHint = $('#canvas-empty');

function loadSaved() {
  try {
    const save = JSON.parse(localStorage.getItem('trackmasters-save') || '{}');
    if (save.points?.length > 5) { state.points = save.points; state.built = !!save.built; }
    for (const key of ['credits', 'xp', 'podiums', 'races']) if (Number.isFinite(save[key])) state[key] = save[key];
    if (save.trackName) $('#track-name').value = save.trackName;
  } catch { /* Start with a clean career if storage is unavailable. */ }
  updateProfile();
}
function save() {
  try { localStorage.setItem('trackmasters-save', JSON.stringify({ points: state.points, built: state.built, credits: state.credits, xp: state.xp, podiums: state.podiums, races: state.races, trackName: $('#track-name').value })); } catch { /* Private browsing can disable storage. */ }
}
function updateProfile() {
  $('#credits').textContent = state.credits.toLocaleString();
  const xp = Math.min(1000, state.xp);
  $$('.profile-xp .progress-line span').forEach(el => { el.style.width = `${xp / 10}%`; });
  $('.xp-label b').textContent = `${xp} / 1,000`;
  $('.profile-bottom').innerHTML = `<span>🏆 &nbsp;${state.podiums} PODIUMS</span><span>🏁 &nbsp;${state.races} RACES</span>`;
  $('.profile-rank>strong').innerHTML = `${state.xp >= 1000 ? '17' : '18'}<small>TH</small>`;
}
function showView(view) {
  state.view = view;
  $$('.page').forEach(page => page.classList.toggle('active', page.id === `${view}-page`));
  $$('.nav-item').forEach(button => button.classList.toggle('active', button.dataset.view === view));
  $('#crumb-title').textContent = view === 'studio' ? 'TRACK STUDIO' : view.toUpperCase();
  if (view === 'studio') requestAnimationFrame(resizeEditor);
  window.scrollTo({ top: 0, behavior: 'smooth' });
}
function canvasSize() {
  const rect = canvas.getBoundingClientRect();
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  if (canvas.width !== Math.round(rect.width * dpr) || canvas.height !== Math.round(rect.height * dpr)) {
    canvas.width = Math.round(rect.width * dpr); canvas.height = Math.round(rect.height * dpr);
  }
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  return { width: rect.width, height: rect.height };
}
function resizeEditor() { if (state.view === 'studio') drawEditor(); }
function drawEditor() {
  const { width, height } = canvasSize();
  ctx.clearRect(0, 0, width, height);
  if (state.points.length < 2 && state.drawingPoints.length < 2) { emptyHint.classList.remove('hidden'); return; }
  emptyHint.classList.add('hidden');
  const points = state.drawing ? state.drawingPoints : state.points;
  drawTrackPath(ctx, points.map(([x, y]) => [x * width, y * height]), state.drawing || state.points.length > 2, state.width * .74, true);
  const start = points[0];
  if (start) {
    ctx.beginPath(); ctx.arc(start[0] * width, start[1] * height, 5, 0, Math.PI * 2);
    ctx.fillStyle = locations[state.location].color; ctx.fill(); ctx.strokeStyle = '#fff'; ctx.lineWidth = 2; ctx.stroke();
  }
  $('#canvas-hint').textContent = state.points.length ? '✦  CIRCUIT READY TO BUILD' : '✦  DRAW A CLOSED LOOP';
  const length = circuitLength(state.points) * 5.2;
  $('#track-length').innerHTML = state.points.length > 2 ? `${length.toFixed(2)} <i>KM</i>` : '— <i>KM</i>';
  $('#turn-readout').textContent = state.points.length > 5 ? countTurns(state.points) : '—';
}
function drawTrackPath(context, points, closed, width, editor = false) {
  if (points.length < 2) return;
  context.save(); context.lineCap = 'round'; context.lineJoin = 'round';
  context.beginPath(); context.moveTo(...points[0]);
  for (let i = 1; i < points.length; i++) context.lineTo(...points[i]);
  if (closed) context.closePath();
  context.strokeStyle = editor ? '#ddd4bd' : '#f2eee2'; context.lineWidth = width + (editor ? 9 : 12); context.stroke();
  context.strokeStyle = '#393e3d'; context.lineWidth = width + (editor ? 5 : 8); context.stroke();
  context.strokeStyle = '#626866'; context.lineWidth = width; context.stroke();
  context.setLineDash([editor ? 10 : 18, editor ? 10 : 18]);
  context.strokeStyle = editor ? '#a6a99b' : '#b9b9a9'; context.lineWidth = editor ? 1 : 2; context.stroke();
  context.setLineDash([]); context.restore();
}
function circuitLength(points) {
  let length = 0;
  for (let i = 0; i < points.length; i++) { const a = points[i], b = points[(i + 1) % points.length]; length += Math.hypot((b[0] - a[0]) * 1.4, b[1] - a[1]); }
  return length;
}
function countTurns(points) {
  let count = 0;
  for (let i = 0; i < points.length; i++) {
    const a = points[(i + points.length - 1) % points.length], b = points[i], c = points[(i + 1) % points.length];
    const v1 = [b[0] - a[0], b[1] - a[1]], v2 = [c[0] - b[0], c[1] - b[1]];
    const angle = Math.acos(Math.max(-1, Math.min(1, (v1[0] * v2[0] + v1[1] * v2[1]) / ((Math.hypot(...v1) * Math.hypot(...v2)) || 1))));
    if (angle > .32) count++;
  }
  return count;
}
function pointerPosition(event) {
  const r = canvas.getBoundingClientRect();
  return [Math.max(.03, Math.min(.97, (event.clientX - r.left) / r.width)), Math.max(.07, Math.min(.93, (event.clientY - r.top) / r.height))];
}
canvas.addEventListener('pointerdown', event => {
  if (state.view !== 'studio') return;
  event.preventDefault(); canvas.setPointerCapture(event.pointerId);
  const point = pointerPosition(event);
  if (state.points.length > 2 && Math.hypot(point[0] - state.points[0][0], point[1] - state.points[0][1]) < .06) { drawEditor(); return; }
  state.drawing = true; state.drawingPoints = [point]; $('#studio-mode').textContent = 'DRAW MODE'; drawEditor();
});
canvas.addEventListener('pointermove', event => {
  if (!state.drawing) return;
  const point = pointerPosition(event), previous = state.drawingPoints.at(-1);
  if (Math.hypot(point[0] - previous[0], point[1] - previous[1]) > .009) { state.drawingPoints.push(point); drawEditor(); }
});
function finishDrawing() {
  if (!state.drawing) return;
  state.drawing = false;
  if (state.drawingPoints.length >= 8) {
    state.points = simplifyPoints(state.drawingPoints, 1);
    if (state.points.length > 90) state.points = state.points.filter((_, i) => i % 2 === 0);
    $('#studio-mode').textContent = 'CIRCUIT COMPLETE'; state.built = false; save();
  }
  state.drawingPoints = []; drawEditor();
}
canvas.addEventListener('pointerup', finishDrawing); canvas.addEventListener('pointercancel', finishDrawing);
function simplifyPoints(points, minDistance) {
  const output = [points[0]];
  for (const point of points.slice(1)) if (Math.hypot(point[0] - output.at(-1)[0], point[1] - output.at(-1)[1]) > minDistance / Math.max(canvas.clientWidth, canvas.clientHeight)) output.push(point);
  return output;
}
function loadDemo() {
  state.points = demoPoints.map(point => [...point]); state.built = false;
  $('#track-name').value = 'MORGAN PARK'; $('#studio-mode').textContent = 'DEMO CIRCUIT LOADED';
  drawEditor(); save(); toast('MORGAN PARK LOADED · READY TO BUILD');
}
function buildCircuit() {
  if (state.points.length < 8) { toast('DRAW A CIRCUIT OR LOAD THE DEMO FIRST'); return; }
  state.built = true; save(); showView('weekend'); toast('CIRCUIT BUILT · LIGHTS ARE CALLING');
}
function toast(message) {
  const el = $('#race-toast'); el.textContent = message; el.classList.add('show');
  clearTimeout(toast.timer); toast.timer = setTimeout(() => el.classList.remove('show'), 2200);
}

function bindNavigation() {
  $$('.nav-item').forEach(button => button.addEventListener('click', () => showView(button.dataset.view)));
  $('#open-studio').addEventListener('click', () => showView('studio'));
  $('#quick-create').addEventListener('click', () => showView('studio'));
  $('#go-weekend').addEventListener('click', () => showView('weekend'));
  $('#weekend-edit').addEventListener('click', () => showView('studio'));
  $$('.back-button').forEach(button => button.addEventListener('click', () => showView('garage')));
  $('#load-demo').addEventListener('click', loadDemo);
  $('#build-track').addEventListener('click', buildCircuit);
  $('#undo-draw').addEventListener('click', () => { state.points = []; state.built = false; $('#studio-mode').textContent = 'DRAW MODE'; drawEditor(); save(); });
  $('#clear-draw').addEventListener('click', () => { state.points = []; state.drawingPoints = []; state.built = false; $('#studio-mode').textContent = 'DRAW MODE'; drawEditor(); save(); });
  $('#width-slider').addEventListener('input', event => {
    state.width = Number(event.target.value); $('#width-value').innerHTML = `${state.width} <small>M</small>`; $('#width-readout').innerHTML = `${state.width} <i>M</i>`;
    event.target.style.background = `linear-gradient(90deg,var(--red) 0%,var(--red) ${(state.width - 8) / 12 * 100}%,#3b4042 ${(state.width - 8) / 12 * 100}%)`; drawEditor();
  });
  $('#location-select').addEventListener('change', event => { state.location = event.target.value; drawEditor(); });
  $$('.condition').forEach(button => button.addEventListener('click', () => {
    $$('.condition').forEach(item => item.classList.toggle('active', item === button)); state.weather = button.dataset.weather;
    const backgrounds = { dry: '#202627', wet: '#1e282c', night: '#171a29' };
    $('.canvas-wrap').style.backgroundColor = backgrounds[state.weather];
  }));
  $('#grid-check').addEventListener('change', event => { state.grid = event.target.checked; event.target.closest('label').querySelector('small').textContent = state.grid ? 'ON' : 'OFF'; });
  $('#pit-check').addEventListener('change', event => { state.pits = event.target.checked; event.target.closest('label').querySelector('small').textContent = state.pits ? 'ON' : 'OFF'; });
  $('#track-name').addEventListener('change', save);
  $('#race-length').addEventListener('change', event => { state.laps = Number(event.target.value); $('#race-lap-label').textContent = `${state.laps} LAPS`; });
  $$('.session-button').forEach(button => button.addEventListener('click', () => startRace(button.dataset.session)));
  $('#career-race').addEventListener('click', () => { showView('weekend'); setTimeout(() => startRace('race'), 250); });
  $('#customize').addEventListener('click', () => toast('APEX R-01 · PERFORMANCE PACKAGE EQUIPPED'));
  $('#inspect-car').addEventListener('click', () => toast('APEX R-01 · POWER 78 · GRIP 67 · AERO 84'));
  $('#result-continue').addEventListener('click', closeRace);
  $('#race-exit').addEventListener('click', closeRace);
  $('#pit-button').addEventListener('click', () => { if (!state.race) return; state.race.pitting = true; $('#pit-overlay').classList.add('active'); $('#pit-instruction').textContent = 'HOLD TO STOP ON THE MARK'; });
  $('#pit-close').addEventListener('click', () => $('#pit-overlay').classList.remove('active'));
  $$('.tire-option').forEach(button => button.addEventListener('click', () => { $$('.tire-option').forEach(item => item.classList.toggle('active', item === button)); state.race && (state.race.selectedTire = button.dataset.tire); }));
  $('#pit-action').addEventListener('pointerdown', beginPitStop);
  ['pointerup', 'pointercancel', 'pointerleave'].forEach(name => $('#pit-action').addEventListener(name, endPitStop));
  $$('.steer-control,.pedal').forEach(button => {
    const control = button.dataset.control;
    button.addEventListener('pointerdown', event => { event.preventDefault(); button.setPointerCapture(event.pointerId); state.touch.add(control); });
    ['pointerup','pointercancel','lostpointercapture'].forEach(name => button.addEventListener(name, () => state.touch.delete(control)));
  });
  document.addEventListener('keydown', event => {
    if (['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(event.key)) event.preventDefault();
    state.keys.add(event.key.toLowerCase());
    if (event.key === 'Escape') { $('#pit-overlay').classList.remove('active'); if ($('#race-screen').classList.contains('active')) closeRace(); }
  });
  document.addEventListener('keyup', event => state.keys.delete(event.key.toLowerCase()));
  window.addEventListener('resize', resizeEditor);
  window.addEventListener('beforeunload', save);
}
let pitInterval = null, pitStarted = 0;
function beginPitStop(event) {
  event.preventDefault(); if (!state.race || !state.race.pitting) return;
  clearInterval(pitInterval); pitStarted = performance.now(); $('#pit-instruction').textContent = 'HOLD STEADY · CHANGE ALL FOUR';
  $('#pit-action').textContent = 'HOLDING…';
  pitInterval = setInterval(() => {
    const progress = Math.min(1, (performance.now() - pitStarted) / 1600);
    $('#pit-meter-fill').style.width = `${progress * 100}%`;
    $('#pit-timer').textContent = `PIT TIME   ${(progress * 2.4).toFixed(2)}`;
    if (progress === 1) {
      clearInterval(pitInterval); $('#pit-overlay').classList.remove('active'); $('#pit-action').innerHTML = 'HOLD TO STOP <span>↗</span>';
      state.race.tire = state.race.selectedTire || 'SOFT'; state.race.tireHealth = 100; state.race.pitting = false;
      $('#tire-status').textContent = `${state.race.tire} · 100%`; $('#pit-meter-fill').style.width = '0%'; toast(`${state.race.tire} TYRES FITTED · BOX BOX`);
    }
  }, 30);
}
function endPitStop() {
  if (!pitInterval) return;
  clearInterval(pitInterval); pitInterval = null; $('#pit-action').innerHTML = 'HOLD TO STOP <span>↗</span>';
  $('#pit-instruction').textContent = 'HOLD TO STOP ON THE MARK'; $('#pit-meter-fill').style.width = '0%';
}
function startRace(session) {
  state.session = session;
  if (!state.built && !state.points.length) { state.points = demoPoints.map(point => [...point]); $('#track-name').value = 'MONTE CARLO'; }
  const screen = $('#race-screen'); screen.classList.add('active'); screen.setAttribute('aria-hidden', 'false');
  $('#result-overlay').classList.remove('active'); $('#pit-overlay').classList.remove('active');
  const maxLaps = session === 'practice' ? 99 : session === 'qualifying' ? 1 : state.laps;
  state.race = { session, maxLaps, lap: 1, progress: .025, speed: 0, lateral: 0, steer: 0, lastTime: 0, bestTime: Infinity, lapStart: performance.now(), started: false, countdown: 3.2, tire: 'SOFT', tireHealth: 100, pitting: false, selectedTire: 'SOFT', finish: false };
  $('#race-mode-label').textContent = session.toUpperCase(); $('#lap-display').textContent = `1 / ${maxLaps}`; $('#race-position').textContent = session === 'practice' ? 'P1' : 'P4';
  $('#best-time').textContent = '—:—.---'; $('#last-time').textContent = '—:—.---'; $('#speed-value').textContent = '000';
  $('#tire-status').textContent = 'SOFT · 100%';
  const count = $('#race-countdown'); count.style.display = 'block'; count.innerHTML = '<span>GET READY</span><b>3</b>';
  toast(session === 'practice' ? 'PRACTICE SESSION · FIND YOUR LINE' : 'LIGHTS OUT · GO GO GO');
  cancelAnimationFrame(state.frame); raceLoop(performance.now());
}
function closeRace() {
  if (state.race?.started && !state.race.finish && state.session !== 'practice') { toast('SESSION ABANDONED'); }
  cancelAnimationFrame(state.frame); state.race = null;
  $('#race-screen').classList.remove('active'); $('#race-screen').setAttribute('aria-hidden','true');
  $('#result-overlay').classList.remove('active'); $('#pit-overlay').classList.remove('active'); showView('garage');
}
function formatTime(ms) {
  const minutes = Math.floor(ms / 60000), seconds = Math.floor(ms / 1000) % 60, millis = Math.floor(ms % 1000);
  return `${minutes}:${String(seconds).padStart(2,'0')}.${String(millis).padStart(3,'0')}`;
}
function raceLoop(now) {
  const race = state.race; if (!race) return;
  const dt = Math.min(.04, (now - (race.lastFrame || now)) / 1000); race.lastFrame = now;
  if (!race.started) {
    race.countdown -= dt;
    const number = Math.max(1, Math.ceil(race.countdown));
    $('#race-countdown b').textContent = race.countdown <= .2 ? 'GO!' : number;
    if (race.countdown <= 0) { race.started = true; $('#race-countdown').style.display = 'none'; race.lapStart = now; }
  } else if (!race.pitting && !race.finish) updateRace(dt, now);
  renderRace(); state.frame = requestAnimationFrame(raceLoop);
}
function inputActive(...names) { return names.some(name => state.keys.has(name) || state.touch.has(name)); }
function updateRace(dt, now) {
  const race = state.race, throttle = inputActive('w','arrowup','accel'), braking = inputActive('s','arrowdown','brake'), left = inputActive('a','arrowleft','left'), right = inputActive('d','arrowright','right');
  const targetSteer = (left ? -1 : 0) + (right ? 1 : 0);
  race.steer += (targetSteer - race.steer) * Math.min(1, dt * 5);
  const handbrake = inputActive(' ');
  if (throttle) race.speed += 62 * dt; else race.speed -= 10 * dt;
  if (braking) race.speed -= 95 * dt;
  if (handbrake) race.speed -= 38 * dt;
  race.speed = Math.max(0, Math.min(290, race.speed));
  const grip = Math.max(.58, race.tireHealth / 100) * (state.weather === 'wet' ? .74 : 1);
  race.lateral += race.steer * (race.speed / 290) * dt * .64 / grip;
  race.lateral *= Math.pow(.982, dt * 60);
  if (Math.abs(race.lateral) > .85) { race.speed = Math.max(0, race.speed - 46 * dt); race.lateral = Math.max(-1.08, Math.min(1.08, race.lateral)); }
  race.speed = Math.max(0, race.speed - (Math.abs(race.steer) * race.speed * .025 + (handbrake ? 0 : 0)) * dt);
  const speedFactor = race.speed < 35 ? .13 : race.speed / 290;
  race.progress += speedFactor * dt / (race.session === 'practice' ? 18 : 13);
  race.tireHealth = Math.max(0, race.tireHealth - (race.speed / 290) * dt * .075);
  $('#speed-value').textContent = String(Math.round(race.speed)).padStart(3,'0');
  $('#tire-status').textContent = `${race.tire} · ${Math.round(race.tireHealth)}%`;
  if (race.progress >= 1) {
    race.progress -= 1; race.lap++;
    race.lastTime = now - race.lapStart; race.lapStart = now;
    race.bestTime = Math.min(race.bestTime, race.lastTime);
    $('#last-time').textContent = formatTime(race.lastTime); $('#best-time').textContent = formatTime(race.bestTime);
    $('#lap-display').textContent = `${Math.min(race.lap, race.maxLaps)} / ${race.maxLaps}`;
    toast(`LAP ${race.lap - 1} · ${formatTime(race.lastTime)}`);
    if (race.lap > race.maxLaps) finishRace();
  }
}

function trackAt(progress, lateral = 0) {
  const points = state.points.length > 5 ? state.points : demoPoints;
  const lengths = []; let total = 0;
  for (let i = 0; i < points.length; i++) { const a=points[i], b=points[(i+1)%points.length]; const len=Math.hypot((b[0]-a[0])*1.15,b[1]-a[1]); lengths.push(len); total+=len; }
  let dist = ((progress % 1) + 1) % 1 * total, segment = 0;
  while (segment < lengths.length - 1 && dist > lengths[segment]) { dist -= lengths[segment]; segment++; }
  const a=points[segment], b=points[(segment+1)%points.length], t=dist/(lengths[segment]||1);
  const px=(a[0]+(b[0]-a[0])*t)*1.15, py=a[1]+(b[1]-a[1])*t;
  const dx=(b[0]-a[0])*1.15, dy=b[1]-a[1], mag=Math.hypot(dx,dy)||1;
  return { x:px, y:py, nx:-dy/mag, ny:dx/mag, angle:Math.atan2(dy,dx) };
}
function renderRace() {
  const host = $('#race-render'), rect = host.getBoundingClientRect();
  if (!state.race) return;
  if (!renderRace.canvas) { renderRace.canvas=document.createElement('canvas'); host.append(renderRace.canvas); renderRace.ctx=renderRace.canvas.getContext('2d'); }
  const c=renderRace.canvas, context=renderRace.ctx, dpr=Math.min(devicePixelRatio||1,2);
  if (c.width!==Math.round(rect.width*dpr)||c.height!==Math.round(rect.height*dpr)) { c.width=Math.round(rect.width*dpr); c.height=Math.round(rect.height*dpr); }
  context.setTransform(dpr,0,0,dpr,0,0);
  const w=rect.width,h=rect.height,race=state.race, location=locations[state.location]||locations.monaco;
  const night=state.weather==='night', wet=state.weather==='wet';
  const sky=context.createLinearGradient(0,0,0,h); sky.addColorStop(0,night?'#111522':wet?'#63747a':'#76aebd'); sky.addColorStop(.52,night?'#414251':wet?'#a2b3b0':'#e5c7a2'); sky.addColorStop(.53,night?'#56565b':'#b8a891'); sky.addColorStop(1,night?'#131a21':'#26312c'); context.fillStyle=sky; context.fillRect(0,0,w,h);
  if (night) { for(let i=0;i<50;i++){const x=(i*173)%w,y=20+(i*59)%(h*.42);context.fillStyle=`rgba(255,230,158,${.35+(i%4)*.1})`;context.fillRect(x,y,2,2);} }
  drawScenery(context,w,h,location,night);
  const horizon=h*.51, playerZ=.92;
  for(let i=20;i>=0;i--){
    const z=(i+1)/21, scale=z*z, p=(race.progress+z*.22)%1, point=trackAt(p);
    const next=trackAt((p+.002)%1), bend=Math.max(-.025,Math.min(.025,(next.x-point.x)*.5));
    const center=w*.5+(point.x-.5)*w*.36*scale+bend*w*scale + Math.sin(p*Math.PI*2)*w*.04*scale;
    const y=horizon+(h*.51)*scale, roadWidth=w*(.055+.42*scale);
    const previous=trackAt((p-.006+1)%1), curvature=Math.sign((next.x-point.x));
    context.fillStyle=wet?'#696d70':'#434849';
    context.beginPath(); context.moveTo(center-roadWidth,y); context.lineTo(center+roadWidth,y); context.lineTo(center+roadWidth*.93,y+5+scale*34); context.lineTo(center-roadWidth*.93,y+5+scale*34); context.closePath(); context.fill();
    context.strokeStyle='#e7e2d4';context.lineWidth=1+scale*5;context.beginPath();context.moveTo(center-roadWidth,y);context.lineTo(center-roadWidth*.93,y+5+scale*34);context.moveTo(center+roadWidth,y);context.lineTo(center+roadWidth*.93,y+5+scale*34);context.stroke();
    if(Math.floor((race.progress+z*.48)*35)%2===0){context.fillStyle=location.color;context.beginPath();context.moveTo(center-roadWidth,y);context.lineTo(center-roadWidth*.95,y+5+scale*34);context.lineTo(center-roadWidth*.83,y+5+scale*34);context.lineTo(center-roadWidth*.88,y);context.fill();context.beginPath();context.moveTo(center+roadWidth,y);context.lineTo(center+roadWidth*.95,y+5+scale*34);context.lineTo(center+roadWidth*.83,y+5+scale*34);context.lineTo(center+roadWidth*.88,y);context.fill();}
