148:   const sky=context.createLinearGradient(0,0,0,h); sky.addColorStop(0,night?'#111522':wet?'#63747a':'#76aebd'); sky.addColorStop(.52,night?'#414251':wet?'#a2b3b0':'#e5c7a2'); sky.addColorStop(.53,night?'#56565b':'#b8a891'); sky.addColorStop(1,night?'#131a21':'#26312c'); context.fillStyle=sky; context.fillRect(0,0,w,h);
149:   if (night) { for(let i=0;i<50;i++){const x=(i*173)%w,y=20+(i*59)%(h*.42);context.fillStyle=`rgba(255,230,158,${.35+(i%4)*.1})`;context.fillRect(x,y,2,2);} }
