const { createRequire } = require('node:module');
const requireRuntime = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = requireRuntime('playwright');
(async () => {
  const browser = await chromium.launch({channel:'chromium', headless:true, args:['--no-sandbox']});
  const page = await browser.newPage({viewport:{width:1280,height:800}});
  const errors=[];
  page.on('pageerror', e=>errors.push(e.message));
  page.on('console', m=>{if(m.type()==='error') errors.push(m.text())});
  await page.goto('http://localhost:3002', {waitUntil:'networkidle'});
  await page.locator('#open-studio').click();
  await page.locator('#pit-check').check();
  await page.locator('#load-demo').click();
  await page.locator('#build-track').click();
  await page.locator('[data-session="race"]').click();
  await page.waitForTimeout(3000);
