const { createRequire } = require('node:module');
const requireRuntime = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = requireRuntime('playwright');
(async () => {
  const browser = await chromium.launch({channel:'chromium', headless:true, args:['--no-sandbox']});
  const page = await browser.newPage({viewport:{width:1280,height:800}});
  const errors=[];
  page.on('pageerror', e=>errors.push(e.message));
  page.on('console', m=>{if(m.type()==='error') errors.push(m.text())});
  await page.goto('http://localhost:3002', {waitUntil:'networkidle'});
  await page.locator('#open-studio').click();
  await page.locator('#pit-check').check();
  await page.locator('#load-demo').click();
  await page.locator('#build-track').click();
  await page.locator('[data-session="race"]').click();
  await page.waitForTimeout(3000);
  await page.locator('#pit-button').click();
  const pitVisible=await page.locator('#pit-overlay').evaluate(el=>getComputedStyle(el).display!=='none');
  await page.locator('.tire-option[data-tire="medium"]').click();
  await page.locator('#pit-action').click();
  const pitClosed=await page.locator('#pit-overlay').evaluate(el=>getComputedStyle(el).display==='none');
  await page.keyboard.down('ArrowUp');
  await page.waitForFunction(()=>document.querySelector('#result-overlay').classList.contains('active'),{timeout:50000});
  await page.keyboard.up('ArrowUp');
  const overlayStyle=await page.locator('#result-overlay').evaluate(el=>({display:getComputedStyle(el).display,z:getComputedStyle(el).zIndex,position:getComputedStyle(el).position,rect:(()=>{const r=el.getBoundingClientRect();return [r.x,r.y,r.width,r.height]})()}));
  const buttonPoint=await page.locator('#result-continue').evaluate(el=>{const r=el.getBoundingClientRect();return [r.x+r.width/2,r.y+r.height/2]});
  const target=await page.evaluate(([x,y])=>document.elementFromPoint(x,y)?.id,[...buttonPoint]);
  await page.screenshot({path:'/tmp/opencode/trackmasters-result.jpg',type:'jpeg',quality:82});
  await page.locator('#result-continue').click();
  const garageVisible=await page.locator('#garage-page').evaluate(el=>el.classList.contains('active'));
  await page.locator('[data-view="career"]').click();
  const career=await page.locator('.career-stats').innerText();
  console.log(JSON.stringify({pitVisible,pitClosed,overlayStyle,target,garageVisible,career,errors},null,2));
  await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});

